{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.CC_sales_consolidated_intermediate as SELECT CAST(region AS STRING) AS region, upper(delivery_country) delivery_country, CAST(cust_id AS STRING) AS customer_id, upper(CAST(Business_Segment AS STRING)) AS Business_Segment, upper(CAST(Brand AS STRING)) AS Brand, upper(CAST(marketplace AS STRING)) AS Shop_name, upper(CAST(marketplace AS STRING)) AS marketplace, upper(CAST(ga4.channel AS STRING)) AS CHANNEL, upper(CAST(ga4.final_source AS STRING)) AS SOURCE, Affiliates, aff_net_name, CAST(order_id AS STRING) AS order_id, CAST(reference_code AS STRING) AS reference_code, CAST(cust_id AS STRING) AS phone, CAST(name AS STRING) AS name, CAST(email AS STRING) AS email, CAST(order_modified_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, CAST(product_id AS STRING) AS sku, CAST(product_id AS STRING) AS product_id, CAST(product_name AS STRING) AS product_name, CAST(currency_code AS STRING) AS CURRENCY, upper(CAST(City AS STRING)) AS City, upper(CAST(State AS STRING)) AS State, CAST(Order_Status AS STRING) AS Order_Status, CAST(order_date AS DATE) AS order_date, CAST(order_timestamp AS TIMESTAMP) AS Order_Time, CAST(product_qty AS FLOAT64) AS quantity, CAST(Selling_Price AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(discount AS FLOAT64) AS DISCOUNT, CAST(TAX AS FLOAT64) AS TAX, CAST(SHIPPING_PRICE AS FLOAT64) AS SHIPPING_PRICE, CAST(Selling_Price AS FLOAT64) AS SELLING_PRICE, CAST(UPPER(order_status) AS STRING) AS OMS_order_status, CAST(UPPER(order_status) AS STRING) AS SHIPPING_STATUS, CAST(UPPER(order_status) AS STRING) AS FINAL_SHIPPING_STATUS, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALEORDERITEMCODE, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALES_ORDER_ITEM_ID, CAST(AWB AS STRING) AS AWB, CAST(Payment_Gateway AS STRING) AS Payment_Gateway, CAST(NULL AS STRING) AS Payment_Mode, CAST(courier_name AS STRING) AS COURIER, CAST(dispatched_date AS date) AS DISPATCH_DATE, CAST(paid_date AS date) AS paid_date, CAST(NULL AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(order_status) LIKE \'delive%\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, CASE WHEN prod_refund_amount IS NOT NULL THEN 1 ELSE 0 END AS RETURN_FLAG, CAST(0 AS FLOAT64) AS returned_quantity, CAST(prod_refund_amount AS FLOAT64) AS returned_sales, CASE WHEN LOWER(afi.order_status) LIKE \'cancel%\' THEN CAST(afi.product_qty AS FLOAT64) END AS cancelled_quantity, CAST(NULL AS STRING) AS NEW_CUSTOMER_FLAG, CAST(NULL AS STRING) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(order_status) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(order_status) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, CAST(afi.SKU AS STRING) AS SKU_CODE, CAST(UPPER(AFI.product_name) AS STRING) AS PRODUCT_NAME_FINAL, CAST(UPPER(AFI.PRODUCT_CATEGORY) AS STRING) AS PRODUCT_CATEGORY, CAST(PRODUCT_SUB_CATEGORY AS STRING) AS PRODUCT_SUB_CATEGORY, CAST(afi.SKU AS STRING) AS commonsku, CAST(NULL AS STRING) AS WAREHOUSE, CAST(zipcode AS STRING) AS pincode, CAST(NULL AS STRING) AS source_pincode, CAST(NULL AS STRING) AS discount_codes, CAST(order_date AS TIMESTAMP) Return_date, Product_Cost, Product_Other_Cost, transaction_id, Order_Date_Flag, Paid_date_Flag, DSF_Cost, shipping_cost_amz, additional_amount FROM maplemonk.website_marketplace_fact_items AS afi left join ( select transactionid, customChannelGroup as final_source, customChannelGroup channel from maplemonk.CC_GA_CUSTOM_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by replace(transactionid, \'#\',\'\') order by 1) =1 ) GA4 on replace(cast(AFI.order_id as string),\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') ; CREATE OR REPLACE TABLE maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT phone AS contact_num, phone FROM maplemonk.CC_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num,e.contact_num) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.CC_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = e.contact_num ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.CC_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.CC_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = o.phone ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email ; ALTER TABLE maplemonk.CC_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.CC_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.CC_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, SELLING_PRICE desc) rw FROM maplemonk.CC_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.CC_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; CREATE OR REPLACE TABLE maplemonk.CC_sales_consolidated AS (Select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, coalesce(sc.region,cf.region) Region, delivery_country, customer_id, Business_Segment, sc.brand as Brand, Shop_name, coalesce(sc.marketplace,cf.marketplace) marketplace, sc.CHANNEL as CHANNEL, SOURCE, Affiliates, aff_net_name, order_id, reference_code, phone, name, email, SHIPPING_LAST_UPDATE_DATE, sku, product_id, product_name, CURRENCY, City, State, Order_Status, coalesce(order_date,cf.date) as order_date, Order_Time, quantity, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, Payment_Gateway, Payment_Mode, COURIER, DISPATCH_DATE, paid_date, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, Product_Cost, Product_Other_Cost, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) as Percent, null as Refund_Amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(amazon_comm,0) as amazon_comm, safe_divide(ifnull(chargeback,0) ,count(*) OVER (PARTITION BY coalesce(sc.order_date,cf.date), coalesce(lower(sc.marketplace), lower(cf.marketplace)), coalesce(lower(sc.region),lower(cf.region)))) as chargeback_amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(storage_fee,0) as storage_fee, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(Outbound_Charges,0) as Outbound_Charges, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(removal_charges,0) as removal_charges, null as Affiliation_Cost, null as spend, ifnull(Order_Date_Flag,0) Order_Date_Flag, ifnull(Paid_date_Flag,0) Paid_date_Flag, 0 as returns_union, 0 as Return_product_cost, 0 as Return_tax, DSF_Cost, shipping_cost_amz, additional_amount from MAPLEMONK.CC_sales_consolidated SC left join ( select order_id as op_order_id ,sum(ifnull(amazon_comm,0)) amazon_comm ,sum(ifnull(storage_fee,0)) storage_fee ,sum(ifnull(postage_fee,0)) Outbound_Charges ,sum(ifnull(removal_charges,0)) removal_charges from cc_comfort_db.order_processing group by 1 )op on lower(cast(op.op_order_id as string)) = lower(cast(sc.order_id as string)) full outer join maplemonk.chargeback_fact_itmes cf on sc.order_date = cf.date and lower(sc.marketplace) = lower(cf.marketplace) and lower(sc.region) = lower(cf.region) ) union all ( Select null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, null maple_monk_id_phone, region, null delivery_country, null customer_id, null Business_Segment, brand, marketplace as Shop_name, marketplace, Channel, null SOURCE, null Affiliates, null aff_net_name, opr_order_id order_id, opr_order_id reference_code, null phone, null name, null email, null SHIPPING_LAST_UPDATE_DATE, sku, null product_id, null product_name, null CURRENCY, null City, null State, null Order_Status, refund_date as Order_date, null Order_Time, null quantity, null GROSS_SALES_BEFORE_TAX, null DISCOUNT, null TAX, null SHIPPING_PRICE, null SELLING_PRICE, null OMS_order_status, null SHIPPING_STATUS, null FINAL_SHIPPING_STATUS, null SALEORDERITEMCODE, null SALES_ORDER_ITEM_ID, null AWB, null Payment_Gateway, null Payment_Mode, null COURIER, refund_date DISPATCH_DATE, refund_date paid_date, null DELIVERED_DATE, null DELIVERED_STATUS, null RETURN_FLAG, null returned_quantity, null returned_sales, null cancelled_quantity, null Days_in_Shipment, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, null WAREHOUSE, null pincode, null source_pincode, null discount_codes, null new_customer_flag, null new_customer_flag_month, null acquisition_product, null acquisition_channel, null acquisition_marketplace, null Product_Cost, null Product_Other_Cost, null as Percent, Refund_Amount as Refund_Amount, null as amazon_comm, null as chargeback_amount, null as storage_fee, null as Outbound_Charges, null as removal_charges, null as Affiliation_Cost, null as spend, 1 Order_Date_Flag, 1 Paid_date_Flag, 1 as returns_union, Return_product_cost, Return_tax, 0 as DSF_Cost, 0 as shipping_cost_amz, 0 as additional_amount from ( ( Select af.opr_order_id, refund_date, brand, region, marketplace, channel, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, sku, sku_code, commonsku, safe_divide((ifnull(Refund_Amount,0)),count(1) over(partition by ifnull(af.opr_order_id,\'\'),refund_date)) Refund_Amount, safe_divide((ifnull(product_cost,0)),count(1) over(partition by ifnull(af.opr_order_id,\'\'),refund_date)) Return_product_cost, safe_divide((ifnull(tax,0)),count(1) over(partition by ifnull(af.opr_order_id,\'\'),refund_date)) Return_tax from ( select cast(opr_archive_refund_date as date) as refund_date ,cast(opr_order_id as string) opr_order_id ,sum(ifnull(opr_refund_amount,0)) Refund_Amount from (select opr.*,decline_reason from cc_comfort_db.order_partial_refund opr left join (select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on cast(opr.opr_order_id as string) = cast(op.order_id as string) ) where upper(opr_refund_status) = \'Y\' and decline_reason != \'Test Order\' and opr_archive_refund_date is not null and cast(opr_order_id as string) not in (select distinct cast(opr_order_id as string) opr_order_id from mp_public.mp_order_partial_refunds) group by 1,2 )af left join ( select distinct order_id, brand, region, marketplace, channel, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, sku, sku_code, product_cost, tax from Maplemonk.cc_sales_consolidated where order_id is not null ) sc on replace(ifnull(cast(af.opr_order_id as string),\'\'),\' \',\'\') = replace(ifnull(cast(sc.order_id as string),\'\'),\' \',\'\') ) UNION ALL select cast(opr_order_id as string), refund_date, brand, region, marketplace, channel, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, sku, sku_code, commonsku, final_refund_amount as Refund_Amount, product_cost as Return_product_cost, final_vat_amount tax from( select cast(opr_archive_refund_date as date) as refund_date, opr_order_id ,opr_stock_code ,sum(safe_divide(ifnull(cast(JSON_EXTRACT_SCALAR((refund_details), \'$.final_refund_amount\') as float64),0) , ifnull(opr_refund_exchange_rate,1))) final_refund_amount ,sum(safe_divide(ifnull(cast(JSON_EXTRACT_SCALAR((refund_details), \'$.final_vat_amount\') as float64),0),ifnull(opr_refund_exchange_rate,1))) final_vat_amount from mp_public.mp_order_partial_refunds group by 1,2,3 )opr left join ( select distinct order_id, brand, sku, SKU_CODE, region, marketplace, channel, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, CURRENCY, product_cost, from Maplemonk.cc_sales_consolidated qualify row_number() over(partition by ifnull(order_id,\'\'),ifnull(SKU_CODE,\'\')) = 1 )sc on cast(opr.opr_order_id as string)= cast(sc.order_id as string) and cast(opr.opr_stock_code as string)= cast(sc.SKU_CODE as string) ) ) ;",
